import bisect
def syt(shape):
    n=sum(shape); res=[]
    def rec(rows,k):
        if k>n: res.append([r[:] for r in rows]); return
        for i in range(len(shape)):
            if len(rows[i])<shape[i] and (i==0 or len(rows[i-1])>len(rows[i])):
                rows[i].append(k); rec(rows,k+1); rows[i].pop()
    rec([[] for _ in shape],1); return res
def ins(T,x):
    T=[r[:] for r in T]
    for i,r in enumerate(T):
        j=bisect.bisect(r,x)
        if j==len(r): r.append(x); return i,j
        r[j],x=x,r[j]
    return len(T),0
for A,B in [(2,2),(3,2),(4,2),(2,3),(4,3),(3,3),(5,2),(5,3),(4,4),(6,2),(2,4),(3,4)]:
    lam=[A]*(B-1)+[A-1]
    ts=syt(lam); N=A*B-1
    g=sum(1 for T in ts if any(ins(T,x+0.5)==(B-1,A-1) for x in range(N+1)))
    print(A,B,len(ts),g)

