from fractions import Fraction
from math import factorial

def hook(shape):
    n = sum(shape)
    cols = [sum(1 for r in shape if r > j) for j in range(shape[0])]
    p = 1
    for i, r in enumerate(shape):
        for j in range(r):
            p *= (r - j - 1) + (cols[j] - i - 1) + 1
    return factorial(n) // p

def g_dp(A, B):
    # SYT of A x B rectangle (B rows of length A) with T[0][A-1] == T[0][A-2] + 1
    cur = {tuple([0] * B): 1}
    for _ in range(A * B):
        nxt = {}
        for s, v in cur.items():
            for i in range(B):
                if s[i] < A and (i == 0 or s[i - 1] > s[i]):
                    t = list(s)
                    if i == 0 and s[0] == A - 2:
                        t[0] = A
                    elif i == 0 and s[0] == A - 1:
                        continue
                    else:
                        t[i] += 1
                    t = tuple(t)
                    nxt[t] = nxt.get(t, 0) + v
        cur = nxt
    return cur.get(tuple([A] * B), 0)

for A in range(2, 8):
    for B in range(2, 8):
        lam = [A] * (B - 1) + [A - 1]
        f = hook(lam)
        g = g_dp(A, B)
        print(A, B, g, Fraction(g, f))

